CREATE VIEW high_altitude_circuits AS 
SELECT * FROM circuits 
WHERE (location_metadata->'coordinates'->>'elevation_m')::numeric > 800;

SELECT hac.name, hac.elevation, (SELECT COUNT(*) FROM races r WHERE r.trkbind = hac.cctkey) as race_count
FROM high_altitude_circuits hac
ORDER BY race_count DESC;
